  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Mobile app", "Premium unlock endpoint", "Receipt validation", "Account database"],
    "dataStores": ["User accounts", "Premium subscriptions"],
    "externalServices": ["App store payment API"],
    "trustBoundaries": ["Client-server boundary"],
    "dataClasses": ["payment"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "Attacker bypasses payment by forging purchased flag",
      "scenario": "An attacker intercepts the POST /premium/unlock request and discovers the server trusts a client-controlled 'purchased' flag. They modify or craft their own request with purchased=true without making any actual purchase, instantly unlocking premium features without payment. This can be automated to create unlimited premium accounts.",
      "component": "Premium unlock endpoint",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        {
          "quote": "The server trusts the client flag \"purchased\": true"
        }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-807"],
      "plainLanguage": "Anyone can get premium features for free by sending a fake 'purchased' flag in their request",
      "requirement": {
        "title": "Server-side receipt verification",
        "given": "a client sends a premium unlock request",
        "when": "the request contains a purchase receipt",
        "then": "the server validates the receipt cryptographically with the app store API and ignores any client-provided purchase flags"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Attacker forges app store receipts",
      "scenario": "Without cryptographic verification of receipts against the app store's public key or API, an attacker crafts fake receipts that appear valid. They generate these fake receipts in bulk and use them to unlock premium on any number of accounts, completely bypassing the payment system.",
      "component": "Receipt validation",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "the app calls POST /premium/unlock with the receipt"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-345"],
      "plainLanguage": "Fake purchase receipts that look real can be used to unlock premium without paying",
      "requirement": {
        "title": "Cryptographic receipt verification",
        "given": "the server receives a purchase receipt",
        "when": "processing a premium unlock request",
        "then": "the receipt must be verified with the app store's API or validated using the store's public key signature"
      }
    },
    {
      "stride": "Tampering",
      "title": "Single receipt unlocks multiple accounts",
      "scenario": "An attacker uses a single legitimate receipt (from their own purchase or obtained from someone else) to unlock premium on dozens of accounts. Without idempotency checks, the same receipt can be submitted repeatedly to different accounts, turning one purchase into unlimited premium access.",
      "component": "Receipt validation",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "the app calls POST /premium/unlock with the receipt"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-294"],
      "plainLanguage": "One person's payment receipt can be reused to give free premium to everyone",
      "requirement": {
        "title": "Single-use receipt enforcement",
        "given": "a receipt has been used to unlock premium",
        "when": "the same receipt is submitted again",
        "then": "the server rejects it and logs the attempt as potential fraud"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Attacker unlocks premium for other users' accounts",
      "scenario": "The unlock endpoint doesn't verify that the authenticated session matches the account being upgraded. An attacker captures their own purchase receipt, then calls the endpoint multiple times with different account identifiers, granting premium to accounts they don't own (friends, followers, sold access).",
      "component": "Premium unlock endpoint",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "the app calls POST /premium/unlock with the receipt"
        }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-639"],
      "plainLanguage": "Someone can pay once and then unlock premium for all their friends' accounts",
      "requirement": {
        "title": "Account ownership verification",
        "given": "a user submits a premium unlock request",
        "when": "the request is authenticated",
        "then": "the server verifies the receipt belongs to and the premium unlock applies only to the authenticated user's own account"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Payment receipts leak in logs or errors",
      "scenario": "If the endpoint logs request bodies or returns receipts in error messages, an attacker with access to logs (insider, compromised monitoring tool, debug endpoint) can harvest valid receipts and replay them to unlock premium on other accounts.",
      "component": "Premium unlock endpoint",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "the app calls POST /premium/unlock with the receipt"
        }
      ],
      "asvs": ["V7.1.1"],
      "cwe": ["CWE-532"],
      "plainLanguage": "Purchase receipts might be saved in logs where other people can find and reuse them",
      "requirement": {
        "title": "Receipt confidentiality",
        "given": "the endpoint processes a purchase receipt",
        "when": "logging or returning errors",
        "then": "receipt data must be redacted and only validated receipt IDs or hashes may be logged"
      }
    }
  ]
}
